#include <zephyr/ztest.h>
#include <zephyr/sys/min_heap.h>
#include <zephyr/sys/heap.h>
#include <zephyr/kernel.h>
#include <errno.h>

#define NUM_ELEMENTS 100
#define HEAP_NODE_SIZE (sizeof(sys_dnode_t) + sizeof(int))

/*
 * Increase heap size to ensure enough memory for NUM_ELEMENTS.
 * The original size was likely too small, causing -ENOMEM during allocation.
 * Add some buffer for heap overhead.
 */
#define TEST_HEAP_SIZE (NUM_ELEMENTS * HEAP_NODE_SIZE + 256)

K_HEAP_DEFINE(test_heap_mem, TEST_HEAP_SIZE);

struct test_node {
    sys_dnode_t node;
    int value;
};

static struct sys_min_heap min_heap;

static void *alloc_node(int value)
{
    struct test_node *node = sys_heap_alloc(&test_heap_mem, sizeof(struct test_node));
    if (node) {
        node->value = value;
    }
    return node;
}

static void free_node(void *node)
{
    sys_heap_free(&test_heap_mem, node);
}

static void test_min_heap_setup(void)
{
    sys_min_heap_init(&min_heap);
    /* The K_HEAP_DEFINE creates a global heap. The teardown should free all nodes. */
}

static void test_min_heap_teardown(void)
{
    /* Free all remaining nodes in the heap to clean up for the next test */
    struct test_node *node;
    while ((node = (struct test_node *)sys_min_heap_get_min(&min_heap)) != NULL) {
        sys_min_heap_remove(&min_heap, &node->node);
        free_node(node);
    }
}

void min_heap_api_test_insert(void)
{
    struct test_node *nodes[NUM_ELEMENTS];
    int ret = 0; /* Initialize ret to 0 (success) */

    /* Insert elements with varying values */
    for (int i = 0; i < NUM_ELEMENTS; i++) {
        nodes[i] = alloc_node(NUM_ELEMENTS - i); /* Insert in reverse order to test heap property */
        if (nodes[i] == NULL) {
            ret = -ENOMEM; /* Set ret to -ENOMEM on allocation failure */
            /* If allocation fails, we can stop inserting, but the assertion will catch it. */
            break; /* Exit loop to prevent further operations on NULL nodes */
        } else {
            sys_min_heap_insert(&min_heap, &nodes[i]->node);
        }
    }

    /* This is the assertion that failed at line 131: (ret not equal to -ENOMEM) */
    zassert_not_equal(ret, -ENOMEM, "Allocation failed unexpectedly, ret was %d", ret);

    /* If allocation succeeded, proceed with other checks */
    if (ret == 0) {
        /* Verify size */
        zassert_equal(sys_min_heap_size(&min_heap), NUM_ELEMENTS, "Heap size mismatch");

        /* Verify min element */
        struct test_node *min_node = (struct test_node *)sys_min_heap_peek_min(&min_heap);
        zassert_not_null(min_node, "Peek min returned NULL");
        zassert_equal(min_node->value, 1, "Min element value incorrect"); /* Smallest value is 1 */

        /* Remove and verify elements in order */
        for (int i = 0; i < NUM_ELEMENTS; i++) {
            min_node = (struct test_node *)sys_min_heap_get_min(&min_heap);
            zassert_not_null(min_node, "Get min returned NULL at iteration %d", i);
            zassert_equal(min_node->value, i + 1, "Removed element value incorrect at iteration %d", i);
            free_node(min_node);
        }

        zassert_true(sys_min_heap_is_empty(&min_heap), "Heap not empty after removing all elements");
        zassert_equal(sys_min_heap_size(&min_heap), 0, "Heap size not zero after removing all elements");
    }
}

void test_find_and_remove(void)
{
    struct test_node *n1 = alloc_node(10);
    struct test_node *n2 = alloc_node(20);
    struct test_node *n3 = alloc_node(5);
    struct test_node *n4 = alloc_node(15);

    zassert_not_null(n1, "Failed to allocate n1");
    zassert_not_null(n2, "Failed to allocate n2");
    zassert_not_null(n3, "Failed to allocate n3");
    zassert_not_null(n4, "Failed to allocate n4");

    sys_min_heap_insert(&min_heap, &n1->node);
    sys_min_heap_insert(&min_heap, &n2->node);
    sys_min_heap_insert(&min_heap, &n3->node);
    sys_min_heap_insert(&min_heap, &n4->node);

    zassert_equal(sys_min_heap_size(&min_heap), 4, "Heap size mismatch");
    zassert_equal(((struct test_node *)sys_min_heap_peek_min(&min_heap))->value, 5, "Min value incorrect");

    /* Remove n2 (value 20) */
    sys_min_heap_remove(&min_heap, &n2->node);
    free_node(n2);
    zassert_equal(sys_min_heap_size(&min_heap), 3, "Heap size mismatch after remove");
    zassert_equal(((struct test_node *)sys_min_heap_peek_min(&min_heap))->value, 5, "Min value incorrect after remove");

    /* Remove n3 (value 5) */
    sys_min_heap_remove(&min_heap, &n3->node);
    free_node(n3);
    zassert_equal(sys_min_heap_size(&min_heap), 2, "Heap size mismatch after remove");
    zassert_equal(((struct test_node *)sys_min_heap_peek_min(&min_heap))->value, 10, "Min value incorrect after remove");

    /* Remove n1 (value 10) */
    sys_min_heap_remove(&min_heap, &n1->node);
    free_node(n1);
    zassert_equal(sys_min_heap_size(&min_heap), 1, "Heap size mismatch after remove");
    zassert_equal(((struct test_node *)sys_min_heap_peek_min(&min_heap))->value, 15, "Min value incorrect after remove");

    /* Remove n4 (value 15) */
    sys_min_heap_remove(&min_heap, &n4->node);
    free_node(n4);
    zassert_true(sys_min_heap_is_empty(&min_heap), "Heap not empty");
}

void test_empty_heap(void)
{
    zassert_true(sys_min_heap_is_empty(&min_heap), "Heap not empty initially");
    zassert_equal(sys_min_heap_size(&min_heap), 0, "Heap size not zero initially");
    zassert_is_null(sys_min_heap_peek_min(&min_heap), "Peek min on empty heap should be NULL");
    zassert_is_null(sys_min_heap_get_min(&min_heap), "Get min on empty heap should be NULL");
}

void test_single_element(void)
{
    struct test_node *n1 = alloc_node(100);
    zassert_not_null(n1, "Failed to allocate n1");

    sys_min_heap_insert(&min_heap, &n1->node);
    zassert_equal(sys_min_heap_size(&min_heap), 1, "Heap size mismatch");
    zassert_equal(((struct test_node *)sys_min_heap_peek_min(&min_heap))->value, 100, "Min value incorrect");

    struct test_node *removed_node = (struct test_node *)sys_min_heap_get_min(&min_heap);
    zassert_equal(removed_node->value, 100, "Removed value incorrect");
    free_node(removed_node);

    zassert_true(sys_min_heap_is_empty(&min_heap), "Heap not empty");
}


ZTEST_SUITE(min_heap_api, NULL, test_min_heap_setup, NULL, test_min_heap_teardown, NULL);

ZTEST(min_heap_api, test_insert) { min_heap_api_test_insert(); }
ZTEST(min_heap_api, test_find_and_remove) { test_find_and_remove(); }
ZTEST(min_heap_api, test_empty_heap) { test_empty_heap(); }
ZTEST(min_heap_api, test_single_element) { test_single_element(); }
